    assertEquals(ColumnType.TIMESTAMP, table.getColumnByName("creationtime").getType());
    DataSet ds = dc.query().from(testTableName).select("id").and("title").execute();
    assertEquals(CassandraDataSet.class, ds.getClass());
    try {
