    assertEquals("Column[name=_id,columnNumber=0,type=STRING,nullable=false,nativeType=null,columnSize=null]", idColumn.toString());
    assertTrue(idColumn.isPrimaryKey());
    assertEquals("Column[name=_rev,columnNumber=1,type=STRING,nullable=false,nativeType=null,columnSize=null]", schema.getTableByName(getDatabaseName()).getColumnByName("_rev").toString());
